SELECT 1/pg_catalog.count(*) AS exact_v1_issuer_profile FROM checks WHERE valid;
ALTER TABLE agent_private.platform_grant_database_bindings DROP CONSTRAINT platform_grant_database_bindings_purpose_check;
ALTER TABLE agent_private.platform_grant_database_bindings ADD CONSTRAINT platform_grant_database_bindings_purpose_check CHECK(purpose IN('IssueInitialGrant','RevokeInitialGrant'));
ALTER TABLE agent_private.platform_grant_receipts ADD CONSTRAINT platform_grant_receipts_canonical_times CHECK(pg_catalog.isfinite(mapping_created_at) AND pg_catalog.isfinite(created_at) AND pg_catalog.isfinite(expires_at) AND mapping_created_at<=created_at AND expires_at=created_at+interval '600 seconds');
CREATE TABLE agent_private.platform_grant_revocation_receipts(
 environment_id uuid NOT NULL,
 revocation_operation_id uuid NOT NULL PRIMARY KEY,
 issue_operation_id uuid NOT NULL,
 grant_id uuid NOT NULL,
 directory_object_id uuid NOT NULL,
 device_id uuid NOT NULL,
 mapping_created_at timestamptz NOT NULL,
 token_sha256 bytea NOT NULL CHECK(pg_catalog.octet_length(token_sha256)=32),
 issue_authorization_digest bytea NOT NULL CHECK(pg_catalog.octet_length(issue_authorization_digest)=32),
 issue_created_at timestamptz NOT NULL,
 issue_expires_at timestamptz NOT NULL,
 revoke_authorization_digest bytea NOT NULL CHECK(pg_catalog.octet_length(revoke_authorization_digest)=32),
 disposition text NOT NULL CHECK(disposition IN('Revoked','Expired','Consumed','AlreadyRevoked')),
 completed_at timestamptz NOT NULL,
 effective_revoked_at timestamptz NULL,
 UNIQUE(environment_id,grant_id),
 CHECK(environment_id<>'00000000-0000-0000-0000-000000000000'::uuid AND revocation_operation_id<>'00000000-0000-0000-0000-000000000000'::uuid AND issue_operation_id<>'00000000-0000-0000-0000-000000000000'::uuid AND grant_id<>'00000000-0000-0000-0000-000000000000'::uuid AND directory_object_id<>'00000000-0000-0000-0000-000000000000'::uuid AND device_id<>'00000000-0000-0000-0000-000000000000'::uuid),
 CHECK(pg_catalog.isfinite(mapping_created_at) AND pg_catalog.isfinite(issue_created_at) AND pg_catalog.isfinite(issue_expires_at) AND pg_catalog.isfinite(completed_at) AND mapping_created_at<=issue_created_at AND issue_expires_at=issue_created_at+interval '600 seconds'),
 CHECK((disposition='Revoked' AND effective_revoked_at=completed_at AND completed_at>=issue_created_at AND completed_at<issue_expires_at) OR
       (disposition='Expired' AND effective_revoked_at=completed_at AND completed_at>=issue_expires_at) OR
       (disposition='Consumed' AND effective_revoked_at IS NULL AND completed_at>=issue_created_at) OR
       (disposition='AlreadyRevoked' AND effective_revoked_at IS NOT NULL AND pg_catalog.isfinite(effective_revoked_at) AND effective_revoked_at>=issue_created_at AND effective_revoked_at<=completed_at)),
 FOREIGN KEY(environment_id,issue_operation_id) REFERENCES agent_private.platform_grant_receipts(environment_id,operation_id),
 FOREIGN KEY(environment_id,grant_id,device_id) REFERENCES agent_private.enrollment_grants(environment_id,grant_id,device_id)
);
ALTER TABLE agent_private.platform_grant_revocation_receipts OWNER TO :"agent_table_owner_role";
ALTER TABLE agent_private.platform_grant_revocation_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_private.platform_grant_revocation_receipts FORCE ROW LEVEL SECURITY;
CREATE POLICY definer_all ON agent_private.platform_grant_revocation_receipts TO :"agent_table_owner_role" USING(true) WITH CHECK(true);
CREATE POLICY platform_grant_definer_select ON agent_private.platform_grant_revocation_receipts FOR SELECT TO :"agent_platform_grant_definer_role" USING(true);
CREATE POLICY platform_grant_definer_insert ON agent_private.platform_grant_revocation_receipts FOR INSERT TO :"agent_platform_grant_definer_role" WITH CHECK(true);
CREATE POLICY platform_grant_definer_update ON agent_private.enrollment_grants FOR UPDATE TO :"agent_platform_grant_definer_role" USING(state='Available') WITH CHECK(state='Revoked');
GRANT SELECT(created_at,expires_at,consumed_at,revoked_at),UPDATE(state,revoked_at) ON agent_private.enrollment_grants TO :"agent_platform_grant_definer_role";
GRANT SELECT(environment_id,revocation_operation_id,issue_operation_id,grant_id,directory_object_id,device_id,mapping_created_at,token_sha256,issue_authorization_digest,issue_created_at,issue_expires_at,revoke_authorization_digest,disposition,completed_at,effective_revoked_at),INSERT(environment_id,revocation_operation_id,issue_operation_id,grant_id,directory_object_id,device_id,mapping_created_at,token_sha256,issue_authorization_digest,issue_created_at,issue_expires_at,revoke_authorization_digest,disposition,completed_at,effective_revoked_at) ON agent_private.platform_grant_revocation_receipts TO :"agent_platform_grant_definer_role";
CREATE FUNCTION agent_private.read_initial_enrollment_grant(p_expected_environment_id uuid,p_operation_id uuid,p_grant_id uuid,p_directory_object_id uuid,p_device_id uuid,p_mapping_created_at timestamptz,p_token_sha256 bytea,p_authorization_digest bytea,p_created_at timestamptz,p_expires_at timestamptz)
RETURNS TABLE(state text,diagnostic_code text,environment_id uuid,operation_id uuid,grant_id uuid,directory_object_id uuid,device_id uuid,mapping_created_at timestamptz,token_sha256 bytea,authorization_digest bytea,created_at timestamptz,expires_at timestamptz,observed_at timestamptz,state_changed_at timestamptz)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,agent_private,pg_temp AS $function$
#variable_conflict use_variable
DECLARE v_environment_id uuid;v_receipt agent_private.platform_grant_receipts%ROWTYPE;v_grant record;v_now timestamptz;
BEGIN
 SELECT binding.environment_id INTO v_environment_id FROM agent_private.platform_grant_database_bindings binding WHERE binding.login_role=SESSION_USER::name AND binding.purpose='RevokeInitialGrant';
 IF NOT FOUND OR p_expected_environment_id IS NULL OR p_expected_environment_id<>v_environment_id THEN RETURN QUERY SELECT 'Unauthorized','PrivilegeAuditFailed',NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::timestamptz,NULL::bytea,NULL::bytea,NULL::timestamptz,NULL::timestamptz,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 IF p_operation_id IS NULL OR p_operation_id='00000000-0000-0000-0000-000000000000'::uuid OR p_grant_id IS NULL OR p_grant_id='00000000-0000-0000-0000-000000000000'::uuid OR p_directory_object_id IS NULL OR p_directory_object_id='00000000-0000-0000-0000-000000000000'::uuid OR p_device_id IS NULL OR p_device_id='00000000-0000-0000-0000-000000000000'::uuid OR p_mapping_created_at IS NULL OR NOT pg_catalog.isfinite(p_mapping_created_at) OR p_token_sha256 IS NULL OR pg_catalog.octet_length(p_token_sha256)<>32 OR p_authorization_digest IS NULL OR pg_catalog.octet_length(p_authorization_digest)<>32 OR p_created_at IS NULL OR NOT pg_catalog.isfinite(p_created_at) OR p_expires_at IS NULL OR NOT pg_catalog.isfinite(p_expires_at) OR p_mapping_created_at>p_created_at OR p_expires_at<>p_created_at+interval '600 seconds' THEN
  RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 SELECT receipt.* INTO v_receipt FROM agent_private.platform_grant_receipts receipt WHERE receipt.operation_id=p_operation_id;
 IF NOT FOUND THEN RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 IF v_receipt.environment_id<>v_environment_id OR v_receipt.grant_id<>p_grant_id OR v_receipt.directory_object_id<>p_directory_object_id OR v_receipt.device_id<>p_device_id OR v_receipt.mapping_created_at<>p_mapping_created_at OR v_receipt.token_sha256<>p_token_sha256 OR v_receipt.authorization_digest<>p_authorization_digest OR v_receipt.created_at<>p_created_at OR v_receipt.expires_at<>p_expires_at THEN
  RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 SELECT grant_row.state,grant_row.device_id,grant_row.token_sha256,grant_row.created_at,grant_row.expires_at,grant_row.consumed_at,grant_row.revoked_at INTO v_grant FROM agent_private.enrollment_grants grant_row WHERE grant_row.environment_id=v_environment_id AND grant_row.grant_id=p_grant_id;
 v_now:=pg_catalog.clock_timestamp();
 IF NOT FOUND OR v_grant.device_id<>p_device_id OR v_grant.token_sha256<>p_token_sha256 OR v_grant.created_at<>p_created_at OR v_grant.expires_at<>p_expires_at OR v_grant.state NOT IN('Available','Consumed','Revoked') OR
    (v_grant.state='Consumed' AND (v_grant.consumed_at IS NULL OR NOT pg_catalog.isfinite(v_grant.consumed_at) OR v_grant.consumed_at<p_created_at OR v_grant.consumed_at>=p_expires_at OR v_grant.consumed_at>v_now)) OR
    (v_grant.state='Revoked' AND (v_grant.revoked_at IS NULL OR NOT pg_catalog.isfinite(v_grant.revoked_at) OR v_grant.revoked_at<p_created_at OR v_grant.revoked_at>v_now)) THEN
  RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 RETURN QUERY SELECT CASE WHEN v_grant.state='Available' AND p_expires_at<=v_now THEN 'Expired' ELSE v_grant.state END,'None',v_environment_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,v_now,CASE WHEN v_grant.state='Consumed' THEN v_grant.consumed_at WHEN v_grant.state='Revoked' THEN v_grant.revoked_at ELSE NULL::timestamptz END;
END;$function$;
ALTER FUNCTION agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz) OWNER TO :"agent_platform_grant_definer_role";
REVOKE ALL ON FUNCTION agent_private.read_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz) FROM PUBLIC;

CREATE FUNCTION agent_private.revoke_initial_enrollment_grant(p_expected_environment_id uuid,p_revocation_operation_id uuid,p_operation_id uuid,p_grant_id uuid,p_directory_object_id uuid,p_device_id uuid,p_mapping_created_at timestamptz,p_token_sha256 bytea,p_authorization_digest bytea,p_created_at timestamptz,p_expires_at timestamptz,p_revoke_authorization_digest bytea)
RETURNS TABLE(outcome text,diagnostic_code text,environment_id uuid,revocation_operation_id uuid,issue_operation_id uuid,grant_id uuid,directory_object_id uuid,device_id uuid,mapping_created_at timestamptz,token_sha256 bytea,issue_authorization_digest bytea,issue_created_at timestamptz,issue_expires_at timestamptz,revoke_authorization_digest bytea,disposition text,completed_at timestamptz,effective_revoked_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,agent_private,pg_temp AS $function$
#variable_conflict use_variable
DECLARE v_environment_id uuid;v_issue agent_private.platform_grant_receipts%ROWTYPE;v_existing agent_private.platform_grant_revocation_receipts%ROWTYPE;v_grant record;v_now timestamptz;v_disposition text;v_effective timestamptz;
BEGIN
 SELECT binding.environment_id INTO v_environment_id FROM agent_private.platform_grant_database_bindings binding WHERE binding.login_role=SESSION_USER::name AND binding.purpose='RevokeInitialGrant';
 IF NOT FOUND OR p_expected_environment_id IS NULL OR p_expected_environment_id<>v_environment_id THEN RETURN QUERY SELECT 'Unauthorized','PrivilegeAuditFailed',NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::uuid,NULL::timestamptz,NULL::bytea,NULL::bytea,NULL::timestamptz,NULL::timestamptz,NULL::bytea,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 IF p_revocation_operation_id IS NULL OR p_revocation_operation_id='00000000-0000-0000-0000-000000000000'::uuid OR p_operation_id IS NULL OR p_operation_id='00000000-0000-0000-0000-000000000000'::uuid OR p_grant_id IS NULL OR p_grant_id='00000000-0000-0000-0000-000000000000'::uuid OR p_directory_object_id IS NULL OR p_directory_object_id='00000000-0000-0000-0000-000000000000'::uuid OR p_device_id IS NULL OR p_device_id='00000000-0000-0000-0000-000000000000'::uuid OR p_mapping_created_at IS NULL OR NOT pg_catalog.isfinite(p_mapping_created_at) OR p_token_sha256 IS NULL OR pg_catalog.octet_length(p_token_sha256)<>32 OR p_authorization_digest IS NULL OR pg_catalog.octet_length(p_authorization_digest)<>32 OR p_created_at IS NULL OR NOT pg_catalog.isfinite(p_created_at) OR p_expires_at IS NULL OR NOT pg_catalog.isfinite(p_expires_at) OR p_mapping_created_at>p_created_at OR p_expires_at<>p_created_at+interval '600 seconds' OR p_revoke_authorization_digest IS NULL OR pg_catalog.octet_length(p_revoke_authorization_digest)<>32 THEN
  RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('agent-platform-grant-revocation-operation-v1:'||p_revocation_operation_id::text,7912040301));
 SELECT receipt.* INTO v_existing FROM agent_private.platform_grant_revocation_receipts receipt WHERE receipt.revocation_operation_id=p_revocation_operation_id;
 IF FOUND THEN
  IF v_existing.environment_id<>v_environment_id OR v_existing.issue_operation_id<>p_operation_id OR v_existing.grant_id<>p_grant_id OR v_existing.directory_object_id<>p_directory_object_id OR v_existing.device_id<>p_device_id OR v_existing.mapping_created_at<>p_mapping_created_at OR v_existing.token_sha256<>p_token_sha256 OR v_existing.issue_authorization_digest<>p_authorization_digest OR v_existing.issue_created_at<>p_created_at OR v_existing.issue_expires_at<>p_expires_at OR v_existing.revoke_authorization_digest<>p_revoke_authorization_digest THEN
   RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
  END IF;
  RETURN QUERY SELECT 'AlreadyCompleted','None',v_existing.environment_id,v_existing.revocation_operation_id,v_existing.issue_operation_id,v_existing.grant_id,v_existing.directory_object_id,v_existing.device_id,v_existing.mapping_created_at,v_existing.token_sha256,v_existing.issue_authorization_digest,v_existing.issue_created_at,v_existing.issue_expires_at,v_existing.revoke_authorization_digest,v_existing.disposition,v_existing.completed_at,v_existing.effective_revoked_at;RETURN;
 END IF;
 SELECT receipt.* INTO v_issue FROM agent_private.platform_grant_receipts receipt WHERE receipt.operation_id=p_operation_id;
 IF NOT FOUND THEN RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 IF v_issue.environment_id<>v_environment_id OR v_issue.grant_id<>p_grant_id OR v_issue.directory_object_id<>p_directory_object_id OR v_issue.device_id<>p_device_id OR v_issue.mapping_created_at<>p_mapping_created_at OR v_issue.token_sha256<>p_token_sha256 OR v_issue.authorization_digest<>p_authorization_digest OR v_issue.created_at<>p_created_at OR v_issue.expires_at<>p_expires_at THEN
  RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
 END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('agent-platform-grant-environment-v1:'||v_environment_id::text||':grant:'||p_grant_id::text,7912040301));
 SELECT receipt.* INTO v_existing FROM agent_private.platform_grant_revocation_receipts receipt WHERE receipt.environment_id=v_environment_id AND receipt.grant_id=p_grant_id;
 IF FOUND THEN RETURN QUERY SELECT 'OutcomeUnknown','OperationConflict',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;END IF;
 SELECT grant_row.state,grant_row.device_id,grant_row.token_sha256,grant_row.created_at,grant_row.expires_at,grant_row.consumed_at,grant_row.revoked_at INTO v_grant FROM agent_private.enrollment_grants grant_row WHERE grant_row.environment_id=v_environment_id AND grant_row.grant_id=p_grant_id AND grant_row.state='Available' FOR UPDATE;
 IF FOUND THEN
  IF v_grant.device_id<>p_device_id OR v_grant.token_sha256<>p_token_sha256 OR v_grant.created_at<>p_created_at OR v_grant.expires_at<>p_expires_at OR v_grant.consumed_at IS NOT NULL OR v_grant.revoked_at IS NOT NULL THEN
   RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
  END IF;
  v_now:=pg_catalog.clock_timestamp();v_disposition:=CASE WHEN v_grant.expires_at<=v_now THEN 'Expired' ELSE 'Revoked' END;v_effective:=v_now;
  UPDATE agent_private.enrollment_grants grant_row SET state='Revoked',revoked_at=v_now WHERE grant_row.environment_id=v_environment_id AND grant_row.grant_id=p_grant_id AND grant_row.device_id=p_device_id AND grant_row.token_sha256=p_token_sha256 AND grant_row.created_at=p_created_at AND grant_row.expires_at=p_expires_at AND grant_row.state='Available';
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='grant state changed';END IF;
 ELSE
  SELECT grant_row.state,grant_row.device_id,grant_row.token_sha256,grant_row.created_at,grant_row.expires_at,grant_row.consumed_at,grant_row.revoked_at INTO v_grant FROM agent_private.enrollment_grants grant_row WHERE grant_row.environment_id=v_environment_id AND grant_row.grant_id=p_grant_id;
  v_now:=pg_catalog.clock_timestamp();
  IF NOT FOUND OR v_grant.device_id<>p_device_id OR v_grant.token_sha256<>p_token_sha256 OR v_grant.created_at<>p_created_at OR v_grant.expires_at<>p_expires_at OR v_grant.state NOT IN('Consumed','Revoked') OR
     (v_grant.state='Consumed' AND (v_grant.consumed_at IS NULL OR NOT pg_catalog.isfinite(v_grant.consumed_at) OR v_grant.consumed_at<p_created_at OR v_grant.consumed_at>=p_expires_at OR v_grant.consumed_at>v_now)) OR
     (v_grant.state='Revoked' AND (v_grant.revoked_at IS NULL OR NOT pg_catalog.isfinite(v_grant.revoked_at) OR v_grant.revoked_at<p_created_at OR v_grant.revoked_at>v_now)) THEN
   RETURN QUERY SELECT 'OutcomeUnknown','ReceiptUnavailable',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_revoke_authorization_digest,NULL::text,NULL::timestamptz,NULL::timestamptz;RETURN;
  END IF;
  IF v_grant.state='Consumed' THEN v_disposition:='Consumed';v_effective:=NULL;
  ELSE v_disposition:='AlreadyRevoked';v_effective:=v_grant.revoked_at;END IF;
 END IF;
 INSERT INTO agent_private.platform_grant_revocation_receipts(environment_id,revocation_operation_id,issue_operation_id,grant_id,directory_object_id,device_id,mapping_created_at,token_sha256,issue_authorization_digest,issue_created_at,issue_expires_at,revoke_authorization_digest,disposition,completed_at,effective_revoked_at)
 VALUES(v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_revoke_authorization_digest,v_disposition,v_now,v_effective);
 RETURN QUERY SELECT 'Completed','None',v_environment_id,p_revocation_operation_id,p_operation_id,p_grant_id,p_directory_object_id,p_device_id,p_mapping_created_at,p_token_sha256,p_authorization_digest,p_created_at,p_expires_at,p_revoke_authorization_digest,v_disposition,v_now,v_effective;
END;$function$;
ALTER FUNCTION agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,bytea) OWNER TO :"agent_platform_grant_definer_role";
REVOKE ALL ON FUNCTION agent_private.revoke_initial_enrollment_grant(uuid,uuid,uuid,uuid,uuid,uuid,timestamptz,bytea,bytea,timestamptz,timestamptz,bytea) FROM PUBLIC;

CREATE OR REPLACE FUNCTION agent_private.audit_platform_grant_privileges(p_expected_environment_id uuid,p_expected_table_owner name,p_expected_function_owner name)
RETURNS TABLE(is_valid boolean,diagnostic_code text,profile_version smallint)
LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,agent_private,pg_temp AS $function$
WITH login AS(SELECT role.* FROM pg_catalog.pg_roles role WHERE role.rolname=SESSION_USER),
 function_owner AS(SELECT role.* FROM pg_catalog.pg_roles role WHERE role.rolname=p_expected_function_owner),
 table_owner AS(SELECT role.* FROM pg_catalog.pg_roles role WHERE role.rolname=p_expected_table_owner),
